# All figures use delivered tables only. No expression object is loaded.
source('mp10_immune_endothelial_mechanisms_v1/scripts/common.R');source(file.path(S,'theme.R'));source(file.path(S,'export.R'));suppressPackageStartupMessages(library(ggplot2));jin_setup();figs<-list();plan<-rd('model_plan.tsv');rr<-c('Treg','Tfh/CXCL13-like','Arterial EC','Capillary EC')
export<-function(p,d,stem,w,h,note=''){
 f<-file.path(B,'plot_data',paste0(stem,'.tsv.gz'));fwrite(d,f,sep='\t',na='NA',compress='gzip');custom_theme<-p$theme;files<-jin_export(p+jin_theme()+custom_theme,file.path(B,'figures',stem),width=w,height=h);figs[[stem]]<<-data.table(figure_id=stem,file=unname(files),part=names(files),data_file=f,width_in=w,height_in=h,note=note);cat('Rendered',stem,'\n')
}
label_setting<-function(x){x[,setting:=fcase(primary,'Main',only_dataset!='ALL',paste0('Dataset: ',only_dataset),omit_dataset!='none',paste0('Omit ',omit_dataset),patient!='main','Replace a with b',exposure=='Q95','Q95 exposure',subset=='common','Common High cohort',min_cells==30,'n >= 30',default='Other')];x[,setting:=paste0(setting,' (n=',n_specimens,')')];x}
col_effect<-function(lim,title='Effect')scale_fill_gradient2(low='#2166ac',mid='white',high='#b2182b',limits=c(-lim,lim),oob=scales::squish,na.value='#d9d9d9',name=title,guide=guide_colourbar(display='rectangles'))
v<-label_setting(rd('candidate_sensitivity_effects.tsv')[gene%in%c('NECTIN2','PVR','VEGFA','VEGFB','VEGFC','PGF','MDK','MIF','LGALS9')]);v[,target:=factor(target,levels=c('H50','H10','H05'))];v[,lab:=ifelse(is.na(logFC),'NE',ifelse(FDR<.05,'*',''))];p<-ggplot(v,aes(gene,setting,fill=logFC))+geom_tile(colour='white',linewidth=.4)+geom_text(aes(label=lab),size=3)+facet_wrap(~target,ncol=1,scales='free_y')+col_effect(1,'log2 FC (capped +/-1)')+labs(x='High vs L50; * within-model BH FDR < 0.05',y=NULL);export(p,v,'epi_prespecified_sensitivity',12,19,'All prespecified own/common cohort, cell-count, patient replacement and LODO settings; n is recorded patient units.')
v<-rd('candidate_dataset_paired_descriptive.tsv')[gene%in%c('NECTIN2','PVR','VEGFA','VEGFB','MDK','MIF')];v[,high_definition:=factor(high_definition,levels=c('H50','H10','H05'))];v[,lab:=paste0(n_pairs,' pairs\n',round(100*fraction_positive),'% +')];p<-ggplot(v,aes(dataset,gene,fill=median_paired_difference))+geom_tile(colour='white',linewidth=.4)+geom_text(aes(label=lab),size=3)+facet_wrap(~high_definition,ncol=1)+col_effect(max(abs(v$median_paired_difference)),'Median paired RNA change')+labs(x='Descriptive specimen pairs; percentage = fraction with positive High-Low change',y=NULL);export(p,v,'epi_dataset_direction',12,11,'Normalized expression paired differences; no cellular or biological-repeat P values are implied.')
v<-rd('epi_within_cluster_candidate_changes.tsv')[gene%in%c('NECTIN2','PVR','VEGFA')&min_cells==50];v[,high_definition:=factor(high_definition,levels=c('H50','H10','H05'))];v[,lab:=ifelse(status!='completed',paste0('NE\nn=',n_pairs),paste0('n=',n_pairs,ifelse(q<.05,' *','')))];p<-ggplot(v,aes(gene,factor(cluster),fill=ifelse(status=='completed',median_normalized_difference,NA_real_)))+geom_tile(colour='white',linewidth=.4)+geom_text(aes(label=lab),size=3)+facet_wrap(~high_definition)+col_effect(max(abs(v$median_normalized_difference),na.rm=TRUE),'Median paired RNA change')+labs(x='Existing Epi clusters; * candidate/cluster BH q < 0.05',y='Existing cluster');export(p,v,'epi_within_existing_clusters',12,6,'Clusters are pre-existing expression clusters, not newly inferred malignant states; threshold >=50 cells per state within cluster.')
ac<-rd('activity_associations.tsv.gz');epiids<-plan[primary&kind=='Epi',model_id];tfsel<-unique(ac[resource=='CollecTRI'&model_id%in%epiids][order(sample_model_q),head(.SD,8),by=.(model_id,mask)]$source);v<-merge(ac[resource=='CollecTRI'&model_id%in%epiids&source%in%tfsel],plan[,.(model_id,target)],by='model_id');v[,column:=factor(paste(target,mask,sep='\n'),levels=as.vector(t(outer(c('H50','H10','H05'),c('Full','M20-masked'),paste,sep='\n'))))];v[,lab:=ifelse(sample_model_q<.05,'*','')];p<-ggplot(v,aes(column,source,fill=activity_effect))+geom_tile(colour='white',linewidth=.4)+geom_text(aes(label=lab),size=4)+col_effect(max(abs(v$activity_effect)),'ULM activity change')+labs(x='Epi: n = 39 / 33 / 24; * sample-model BH q < 0.05',y=NULL);export(p,v,'epi_CollecTRI_Full_M20',12,max(7,length(tfsel)*.3),'Same TFs shown for Full and M20-masked; activity changes are not TF RNA fold changes.')
# All receiver Hallmarks remain in the full table; display top eight main enrichments plus predefined angiogenesis/hypoxia.
g<-rd('gsea_sensitivity_results.tsv.gz');for(r in rr){z<-g[kind=='receiver'&target==r&library=='Hallmark'&mask=='Full'];if(!nrow(z))next;paths<-union(z[primary==TRUE][order(padj),head(pathway,8)],paste0('HALLMARK_',c('ANGIOGENESIS','HYPOXIA')));v<-merge(z[pathway%in%paths],rd('model_status.tsv')[,.(model_id,n_specimens)],by='model_id');v<-label_setting(v);v[,lab:=ifelse(padj<.05,'*','')];v[,pathway_label:=gsub('_',' ',sub('HALLMARK_','',pathway))];p<-ggplot(v,aes(setting,pathway_label,fill=NES))+geom_tile(colour='white',linewidth=.4)+geom_text(aes(label=lab),size=4)+col_effect(3,'NES (capped +/-3)')+labs(x=paste0(r,': * Hallmark BH q < 0.05'),y=NULL)+theme(axis.text.x=element_text(angle=45,hjust=1));export(p,v,paste0('Hallmark_sensitivity_',gsub('[^A-Za-z0-9]','_',r)),13,7,'Full prespecified sensitivity results; gene-ranking enrichment is distinct from ligand or patient-level causal evidence.')}
v<-rd('abundance_associations.tsv')[patient=='main'&exposure=='Q50'&omit_dataset=='none'];v[,setting:=paste0(denominator_type,' / >=',min_cells)];v[,lab:=ifelse(status!='completed','NE',paste0('n=',n_recorded_patient_units,ifelse(q<.05,' *','')))];p<-ggplot(v,aes(setting,receiver,fill=estimate))+geom_tile(colour='white',linewidth=.4)+geom_text(aes(label=lab),size=4)+col_effect(max(abs(v$estimate),na.rm=TRUE),'Log-odds effect / exposure SD')+labs(x='Uncapped abundance; * family BH q < 0.05',y=NULL);export(p,v,'receiver_abundance_main_thresholds',12,5,'Quasibinomial model with dataset adjustment; denominator thresholds differ from receiver-expression cell thresholds.')
ns<-merge(rd('nichenet_analysis_status.tsv'),plan[,.(model_id,primary,target)],by='model_id');v<-ns[primary&direction=='Epi_to_TME'&detection_threshold==.1];v[,information:=fcase(status!='completed','Not evaluable',n_targets<10,'Low information',default='Evaluable')];v[,lab:=paste0(ifelse(is.na(n_targets),'NE',paste0(n_targets,' targets')),'\n',ifelse(is.na(n_specimens),'',paste0('n=',n_specimens)))];p<-ggplot(v,aes(target_direction,receiver,fill=information))+geom_tile(colour='white',linewidth=.4)+geom_text(aes(label=lab),size=4)+scale_fill_manual(values=c('Not evaluable'='#d9d9d9','Low information'='#fdd49e','Evaluable'='#74c476'),name='Target information')+labs(x='Own receiver DE targets (local FDR < 0.05; median exposure; >=50 cells)',y=NULL);export(p,v,'nichenet_receiver_information',11,5,'Not evaluable is not negative evidence. Fewer than 10 targets is exploratory, regardless of activity rank.')
nn<-rd('nichenet_ligand_activities.tsv.gz');for(r in rr){id<-plan[primary&target==r&kind=='receiver',model_id];v<-nn[model_id==id&mask=='Full'&detection_threshold==.1&target_direction!='union'&(rank_sender_agnostic<=10|test_ligand%in%c('NECTIN2','PVR','VEGFA'))];if(!nrow(v))next;v[,prediction_status:=ifelse(is.na(pearson),'Constant prior predictions','Variable prior predictions')];v[,test_ligand:=reorder(test_ligand,aupr_corrected)];p<-ggplot(v,aes(aupr_corrected,test_ligand,fill=prediction_status))+geom_col()+facet_wrap(~target_direction)+scale_fill_manual(values=c('Constant prior predictions'='#bdbdbd','Variable prior predictions'='#4c78a8'),name='Prior variability')+labs(x=paste0(r,': corrected AUPR (low-information target set)'),y=NULL);export(p,v,paste0('nichenet_low_information_',gsub('[^A-Za-z0-9]','_',r)),11,6,'Native NicheNet tie handling can give high AUPR for constant predictions; these are flagged and are not mechanistic winners.')}
lk<-rd('nichenet_target_links.tsv.gz');for(id in plan[primary==TRUE,model_id]){v<-lk[model_id==id&mask==(if(plan[model_id==id,kind]=='Epi')'M20-masked'else'Full')&target_direction=='union'];if(!nrow(v))next;tg<-v[,.(best_prior=max(prior_weight),target_logFC=target_logFC[1],target_q=target_q[1]),by=target][order(-best_prior)];tg<-head(tg,15)$target;lg<-unique(v$ligand);w<-v[target%in%tg];w[,target:=factor(target,levels=rev(tg))];p<-ggplot(w,aes(ligand,target,size=prior_weight,colour=target_logFC))+geom_point()+scale_size_continuous(range=c(.3,6),name='Prior weight')+scale_colour_gradient2(low='#2166ac',mid='white',high='#b2182b',limits=c(-3,3),oob=scales::squish,name='Actual target log2 FC',guide=guide_colourbar(display='rectangles'))+labs(x=paste0(plan[model_id==id,target],': prior size and actual target effect (BH q < 0.05)'),y=NULL)+theme(axis.text.x=element_text(angle=45,hjust=1));export(p,w,paste0('nichenet_prior_actual_',id),12,8,'Prior weights are not measured expression changes or evidence of receptor-branch specificity. Targets are selected by actual receiver DE, then top prior weights for display.')}
# Compare Full and M20-masked Epi scores using a common displayed regulon set.
if(file.exists(tb('scenic_Epi_M20-masked_associations.tsv.gz'))){
 full<-rd('scenic_Epi_associations.tsv.gz');masked<-rd('scenic_Epi_M20-masked_associations.tsv.gz');a<-rbindlist(list(full,masked),fill=TRUE);ids<-plan[primary&kind=='Epi',model_id];sel<-union(c('SREBF1(+)','SREBF2(+)'),full[model_id%in%ids][order(sample_model_q),head(regulon,5),by=model_id]$V1)
 v<-merge(CJ(regulon=sel,model_id=ids,mask=c('Full','M20-masked')),a,by=c('regulon','model_id','mask'),all.x=TRUE);v<-merge(v,plan[,.(model_id,target)],by='model_id');v[,column:=factor(paste(target,mask,sep='\n'),levels=as.vector(t(outer(c('H50','H10','H05'),c('Full','M20-masked'),paste,sep='\n'))))];v[,lab:=ifelse(is.na(AUCell_effect),'NE',ifelse(sample_model_q<.05,'*',''))];p<-ggplot(v,aes(column,regulon,fill=AUCell_effect))+geom_tile(colour='white',linewidth=.4)+geom_text(aes(label=lab),size=3.5)+col_effect(max(abs(v$AUCell_effect),na.rm=TRUE),'Mean AUCell change')+labs(x='Epi: n = 39 / 33 / 24; * sample-model BH q < 0.05',y=NULL);export(p,v,'scenic_Epi_Full_M20',12,max(5,length(sel)*.3+1.5),'Common displayed regulons; NE is no motif-pruned/testable regulon. M20 masking removes Top20 targets and downstream ranking background without changing RNA counts, score or groups.')
}
# SCENIC displays are produced only after the corresponding lineage computation has completed.
for(lin in c('Epi','T_lineage','Endothelial')){
 f<-tb(paste0('scenic_',lin,'_associations.tsv.gz'));if(!file.exists(f))next;aa<-merge(fread(f),plan,by='model_id');sel<-unique(aa[primary==TRUE][order(sample_model_q),head(.SD,10),by=model_id]$regulon);v<-aa[primary&regulon%in%sel];v[,column:=paste0(target,' (n=',n_recorded_patient_units,')')];if(lin=='Epi')v[,column:=factor(column,levels=unique(v[order(match(target,c('H50','H10','H05'))),column]))];v[,lab:=ifelse(sample_model_q<.05,'*','')];p<-ggplot(v,aes(column,regulon,fill=AUCell_effect))+geom_tile(colour='white',linewidth=.4)+geom_text(aes(label=lab),size=4)+col_effect(max(abs(v$AUCell_effect)),'Mean AUCell effect')+labs(x='* sample-model BH q < 0.05',y=NULL);export(p,v,paste0('scenic_activity_',lin),12,max(5,length(sel)*.28+1.5),'Same frozen network for each lineage; all eligible cells scored. AUCell is not TF RNA.')
 v<-rd(paste0('scenic_',lin,'_RSS.tsv.gz'))[regulon%in%sel];p<-ggplot(v,aes(subgroup,regulon,fill=RSS))+geom_tile(colour='white',linewidth=.4)+scale_fill_gradient(low='white',high='#54278f',name='RSS',guide=guide_colourbar(display='rectangles'))+labs(x='Descriptive subtype specificity (not MP10 association P)',y=NULL)+theme(axis.text.x=element_text(angle=45,hjust=1));export(p,v,paste0('scenic_RSS_',lin),12,max(5,length(sel)*.28+1.5),'RSS is descriptive and cell weighted. Existing Epi clusters and final T/EC labels are shown; Unavailable existing cluster denotes missing annotation, not a biological subtype.')
 ed<-rd(paste0('scenic_',lin,'_regulon_edges.tsv.gz'));key<-rd(paste0('scenic_',lin,'_key_TF_selection.tsv'));v<-ed[TF%in%key$source&TF!=target][order(-weight),head(.SD,8),by=TF];if(nrow(v)){tfs<-sort(unique(v$TF));targets<-sort(unique(v$target));v[,`:=`(x=0,y=match(TF,tfs)/max(1,length(tfs)),xend=1,yend=match(target,targets)/max(1,length(targets)))];nodes<-rbind(data.table(label=tfs,x=0,y=seq_along(tfs)/length(tfs),type='TF'),data.table(label=targets,x=1,y=seq_along(targets)/length(targets),type='Target'));p<-ggplot(v)+geom_segment(aes(x=x,y=y,xend=xend,yend=yend),linewidth=.4,colour='#bdbdbd',arrow=grid::arrow(length=grid::unit(.07,'inches')))+geom_point(data=nodes,aes(x,y,colour=type),size=2)+geom_text(data=nodes,aes(x,y,label=label,hjust=ifelse(x==0,1.1,-.1)),size=3.5)+scale_colour_manual(values=c(TF='#984ea3',Target='#4daf4a'),name='Network role')+coord_cartesian(xlim=c(-.3,1.45),clip='off')+labs(x='Motif-supported inferred edges (not binding validation)',y=NULL)+theme(axis.text=element_blank(),axis.ticks=element_blank());export(p,v,paste0('scenic_key_network_',lin),11,max(7,length(targets)*.22),'Top eight weighted targets per predefined key TF for display; complete network and second-seed recovery are delivered separately.')}
}
fwrite(rbindlist(figs,fill=TRUE),file.path(B,'config/figure_manifest_extended.tsv'),sep='\t');cat('EXTENDED REPLOT COMPLETE\n')
